-- Datos SINTETICOS. Importacion opcional, una vez, solo desarrollo.
-- Usuario BLOQUEADO y hash NULL: no existe una clave de demostracion.
-- No contiene sesiones ni comandos falsos: no representa cambios de produccion.
USE hackathon_pinguinos_dev;
SET NAMES utf8mb4;
SET SESSION time_zone = '+00:00';
DELIMITER $$
CREATE PROCEDURE hackathon_pinguinos_dev.dbv1_cargar_demo_001()
SQL SECURITY INVOKER
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  IF DATABASE()<>'hackathon_pinguinos_dev' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Base destino incorrecta';
  END IF;
  START TRANSACTION;
  IF NOT EXISTS(SELECT 1 FROM schema_migraciones WHERE version=2)
     OR EXISTS(SELECT 1 FROM schema_semillas WHERE version=1)
     OR EXISTS(SELECT 1 FROM usuarios) OR EXISTS(SELECT 1 FROM negocios) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Demo exige migracion 002 y base sin usuarios/negocios; no repetir';
  END IF;
    VALUES ('00000000-0000-4000-8000-000000000001','Comerciante DEMO ficticio','DEMO-NO-TELEFONO','demo@example.invalid',NULL,'BLOQUEADO');
    VALUES ('00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000001','Dispositivo DEMO','ANDROID');
    VALUES ('00000000-0000-4000-8000-000000000010','Tienda DEMO ficticia','Comercio de demostracion','2026-10-01');
    VALUES ('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000001','PROPIETARIO','00000000-0000-4000-8000-000000000001');
    VALUES ('00000000-0000-4000-8000-000000000300','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000030','00000000-0000-4000-8000-000000000031',1000,'2026-10-01','Transferencia propia DEMO','00000000-0000-4000-8000-000000000001');
    VALUES ('00000000-0000-4000-8000-000000000500','00000000-0000-4000-8000-000000000010','YAPE','image/png',1,REPEAT('0',64),'PENDIENTE','evidencia-demo-no-subida.png','00000000-0000-4000-8000-000000000001');
    VALUES ('00000000-0000-4000-8000-000000000501','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000500','00000000-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000001');
    VALUES ('00000000-0000-4000-8000-000000000600','00000000-0000-4000-8000-000000000010','2026-10-01','CON_ACTIVIDAD','Dia sintetico no es cobertura real','00000000-0000-4000-8000-000000000001');
  COMMIT;
END$$
DELIMITER ;
CALL hackathon_pinguinos_dev.dbv1_cargar_demo_001();
